@import "@fontsource-variable/inter";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";

/* Light (faithful): a #fafafa page, deep navy text (#151e3d), brand violet (#6e56cf),
   pale lavender bands (#f6f2fd), teal (#008573) as the second colour, mint wash (#e3f3ef). */
:root {
  --background: oklch(0.985 0 0);
  --foreground: oklch(0.245 0.06 269.4);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.245 0.06 269.4);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.245 0.06 269.4);
  --primary: oklch(0.542 0.179 288);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.967 0.015 302.6);
  --secondary-foreground: oklch(0.245 0.06 269.4);
  --muted: oklch(0.95 0.005 286.3);
  --muted-foreground: oklch(0.642 0.025 285.7);
  --accent: oklch(0.951 0.018 179.3);
  --accent-foreground: oklch(0.245 0.06 269.4);
  --destructive: oklch(0.6 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.866 0.012 286.1);
  --input: oklch(0.764 0.018 286);
  --ring: oklch(0.542 0.179 288);
  --highlight: oklch(0.552 0.101 178.8);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.633 0.145 290);
  --chart-1: oklch(0.542 0.179 288);
  --chart-2: oklch(0.597 0.209 260.2);
  --chart-3: oklch(0.552 0.101 178.8);
  --chart-4: oklch(0.847 0.199 126.6);
  --chart-5: oklch(0.853 0.043 321);
  --sidebar: oklch(0.967 0.015 302.6);
  --sidebar-foreground: oklch(0.245 0.06 269.4);
  --sidebar-primary: oklch(0.542 0.179 288);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.95 0.005 286.3);
  --sidebar-accent-foreground: oklch(0.245 0.06 269.4);
  --sidebar-border: oklch(0.866 0.012 286.1);
  --sidebar-ring: oklch(0.542 0.179 288);

  --typeface-body: "Inter Variable", Inter, ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", Inter, ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 80rem;
  --page-gutter: 1rem;
  --section-y: 5rem;
}

/* Dark: the navy sections (#151e3d), violet-black cards (#1a1238), a lighter navy for
   popovers and gradients (#1e2a5a), the same violet, and mint (#a1ded2) as the second colour. */
.dark {
  --background: oklch(0.245 0.06 269.4);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.217 0.071 288.8);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.303 0.087 270);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.542 0.179 288);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.303 0.087 270);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.334 0.102 271.1);
  --muted-foreground: oklch(0.642 0.025 285.7);
  --accent: oklch(0.334 0.102 271.1);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.68 0.19 22);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 20%);
  --input: oklch(1 0 0 / 40%);
  --ring: oklch(0.633 0.145 290);
  --highlight: oklch(0.856 0.064 181.2);
  --highlight-foreground: oklch(0.245 0.06 269.4);
  --glow: oklch(0.633 0.145 290);
  --chart-1: oklch(0.633 0.145 290);
  --chart-2: oklch(0.597 0.209 260.2);
  --chart-3: oklch(0.552 0.101 178.8);
  --chart-4: oklch(0.847 0.199 126.6);
  --chart-5: oklch(0.853 0.043 321);
  --sidebar: oklch(0.217 0.071 288.8);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.542 0.179 288);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.334 0.102 271.1);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 20%);
  --sidebar-ring: oklch(0.633 0.145 290);
}
